"""Inline, offline controls. All measurement labels are generated by Python."""

from __future__ import annotations

import base64
import hashlib

SCRIPT = r"""
(() => {
  const root = document.documentElement;
  root.dataset.interactive = 'true';
  const themeButtons = [...document.querySelectorAll('[data-theme-choice]')];
  function setTheme(theme) {
    root.dataset.theme = theme;
    for (const button of themeButtons) {
      button.setAttribute('aria-pressed', String(button.dataset.themeChoice === theme));
    }
  }
  try {
    setTheme(localStorage.getItem('garmin-theme') === 'dark' ? 'dark' : 'light');
  } catch {
    setTheme('light');
  }
  for (const button of themeButtons) {
    button.addEventListener('click', () => {
      const theme = button.dataset.themeChoice;
      setTheme(theme);
      try { localStorage.setItem('garmin-theme', theme); } catch { /* local preview */ }
    });
  }

  function markPage(event) {
    const id = location.hash.slice(1) || 'today';
    const target = document.getElementById(id);
    if (target?.classList.contains('run-section')) target.open = true;
    const page = target?.closest('.page') || document.getElementById('today');
    for (const figure of page.querySelectorAll('[data-chart]:not([data-ready])')) {
      initChart(figure);
    }
    const section = !target ? 'today' : id.startsWith('run-') ? 'running'
      : id.startsWith('workout-') ? 'training' : id === 'recovery' ? 'today'
      : id.startsWith('day-') || id.startsWith('month-') ||
        ['body', 'patterns', 'history'].includes(id) ? 'trends' : id;
    for (const link of document.querySelectorAll('.top a')) {
      if (link.hash === '#' + section) link.setAttribute('aria-current', 'page');
      else link.removeAttribute('aria-current');
    }
    if (event && target?.classList.contains('page')) {
      target.querySelector('h2')?.focus({preventScroll: true});
    }
  }
  markPage();
  window.addEventListener('hashchange', markPage);

  function initChart(figure) {
    const svg = figure.querySelector('svg');
    const readout = figure.querySelector('.chart-readout');
    const primary = readout.querySelector('strong');
    const secondary = readout.querySelector('span');
    const status = figure.querySelector('[role=status]');
    const overlayControls = [...figure.querySelectorAll('[data-overlay-control]')];
    const overlayTracks = [...svg.querySelectorAll('[data-overlay-track]')];
    const cursor = figure.querySelector('.chart-cursor');
    const vertical = cursor.querySelector('.cursor-x');
    const horizontal = cursor.querySelector('.cursor-y');
    const marker = cursor.querySelector('circle');
    const conditions = JSON.parse(figure.dataset.conditions || '[]');
    const points = [...svg.querySelectorAll('[data-point]')].map(el => ({
      x: Number(el.getAttribute('cx')), y: Number(el.getAttribute('cy')),
      title: el.dataset.title, value: el.dataset.value,
      condition: conditions[el.dataset.conditionIndex]
    }));
    let selected = -1;
    let pointer = null;
    let pinned = false;
    let touchOrigin = null;
    let moveFrame = 0;
    let latestMove;
    let overlay = null;
    let overlayReadings = [];
    const scatter = figure.dataset.chart === 'scatter';

    function clear() {
      selected = -1;
      cursor.classList.remove('visible');
      readout.classList.remove('selected');
      primary.textContent = '';
      secondary.textContent = '';
      status.textContent = '';
    }

    function select(index, announce = false) {
      const point = points[index];
      if (!point) return;
      const value = [point.value, point.condition, overlayReadings[index]].filter(Boolean).join(' · ');
      if (announce) status.textContent = point.title + '. ' + value;
      if (index === selected) return;
      selected = index;
      vertical.setAttribute('x1', point.x);
      vertical.setAttribute('x2', point.x);
      horizontal.setAttribute('y1', point.y);
      horizontal.setAttribute('y2', point.y);
      marker.setAttribute('cx', point.x);
      marker.setAttribute('cy', point.y);
      cursor.classList.add('visible');
      readout.classList.add('selected');
      primary.textContent = point.title;
      secondary.textContent = value;
    }

    function selectNearest(clientX, clientY) {
      const matrix = svg.getScreenCTM();
      if (!matrix) return;
      const position = svg.createSVGPoint();
      position.x = clientX;
      position.y = clientY;
      const at = position.matrixTransform(matrix.inverse());
      let nearest = 0;
      let best = Infinity;
      points.forEach(({x, y}, index) => {
        const distance = (at.x - x) ** 2 + (scatter ? (at.y - y) ** 2 : 0);
        if (distance < best) {
          best = distance;
          nearest = index;
        }
      });
      select(nearest);
    }

    function cancelMove() {
      if (moveFrame) cancelAnimationFrame(moveFrame);
      moveFrame = 0;
    }

    function queueMove(event) {
      latestMove = [event.clientX, event.clientY];
      if (moveFrame) return;
      moveFrame = requestAnimationFrame(() => {
        moveFrame = 0;
        selectNearest(...latestMove);
      });
    }

    figure.dataset.ready = 'true';
    for (const button of overlayControls) {
      const readings = JSON.parse(button.dataset.readings);
      button.addEventListener('click', () => {
        const key = button.dataset.overlayControl;
        overlay = overlay === key ? null : key;
        overlayReadings = overlay ? readings : [];
        for (const choice of overlayControls) {
          choice.setAttribute('aria-pressed', String(choice.dataset.overlayControl === overlay));
        }
        for (const track of overlayTracks) {
          track.classList.toggle('active', track.dataset.overlayTrack === overlay);
        }
        const index = selected;
        selected = -1;
        select(index, true);
      });
    }
    svg.setAttribute('tabindex', '0');
    svg.querySelectorAll('title[data-native]').forEach(title => title.remove());
    svg.addEventListener('pointerdown', event => {
      if (!event.isPrimary || event.button !== 0 || pointer !== null) return;
      cancelMove();
      pointer = event.pointerId;
      svg.setPointerCapture(pointer);
      if (event.pointerType === 'touch') {
        // Let a vertical scroll start without flashing a new point.
        touchOrigin = [event.clientX, event.clientY];
      } else {
        selectNearest(event.clientX, event.clientY);
      }
    });
    svg.addEventListener('pointermove', event => {
      if (pointer !== event.pointerId &&
          !(pointer === null && event.pointerType === 'mouse' && !pinned)) return;
      if (touchOrigin) {
        const dx = Math.abs(event.clientX - touchOrigin[0]);
        const dy = Math.abs(event.clientY - touchOrigin[1]);
        if (dx < 6 || dx <= dy) return;
        touchOrigin = null;
      }
      queueMove(event);
    }, { passive: true });
    svg.addEventListener('pointerup', event => {
      if (pointer !== event.pointerId) return;
      cancelMove();
      selectNearest(event.clientX, event.clientY);
      pointer = null;
      touchOrigin = null;
      pinned = event.pointerType !== 'mouse';
    });
    function endGesture(event) {
      if (pointer !== event.pointerId) return;
      cancelMove();
      pointer = null;
      touchOrigin = null;
      if (!pinned) clear();
    }
    svg.addEventListener('pointercancel', endGesture);
    svg.addEventListener('lostpointercapture', endGesture);
    svg.addEventListener('pointerleave', event => {
      if (event.pointerType === 'mouse' && pointer === null && !pinned) {
        cancelMove();
        clear();
      }
    });
    svg.addEventListener('keydown', event => {
      let next;
      switch (event.key) {
        case 'ArrowLeft':
        case 'ArrowUp': next = selected < 0 ? points.length - 1 : selected - 1; break;
        case 'ArrowRight':
        case 'ArrowDown': next = selected + 1; break;
        case 'Home': next = 0; break;
        case 'End': next = points.length - 1; break;
        case 'Escape':
          cancelMove();
          pinned = false;
          clear();
          event.preventDefault();
          return;
        default: return;
      }
      event.preventDefault();
      cancelMove();
      select(Math.min(points.length - 1, Math.max(0, next)), true);
    });
  }
})();
"""

SCRIPT_HASH = base64.b64encode(hashlib.sha256(SCRIPT.encode()).digest()).decode()
CONTENT_POLICY = (
    "default-src 'none'; "
    f"script-src 'sha256-{SCRIPT_HASH}'; "
    "style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"
)
